// Meta webhook payload'undan sadece telefon + mesaj metnini alir.
// KVKK: mesaj icerigi HICBIR YERE YAZILMAZ, yalnizca akis icinde 1/2 karari icin kullanilir.
const b = $input.first().json.body || $input.first().json;
const value = b?.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];
if (!msg) return []; // teslim/okundu bildirimleri: islem yok

let metin = '';
if (msg.type === 'text') metin = msg.text?.body || '';
else if (msg.type === 'button') metin = msg.button?.text || msg.button?.payload || '';
else if (msg.type === 'interactive') metin = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';

return [{ json: { telefon: String(msg.from || '').replace(/\D/g, ''), metin } }];

// 1 = onay, 2 = iptal, digeri = insana devir.
const cfg = $('Ayarlar (Gelen)').first().json;
const gelen = $('Gelen Mesajı Ayrıştır').first().json;
const tel = String(gelen.telefon || '').trim();
const metin = String(gelen.metin || '').trim().toLowerCase();
const rows = $input.all().map((i) => i.json);

const ONAY = ['1', 'evet', 'e', 'ok', 'tamam', 'olur', 'uygun'];
const IPTAL = ['2', 'iptal', 'hayır', 'hayir', 'olmaz', 'değişiklik', 'degisiklik'];
const AKTIF = ['yeni', 'onaylı', 'onayli', 'teklif_edildi'];

function mesaj(govde) {
  return {
    messaging_product: 'whatsapp',
    to: tel,
    type: 'text',
    text: { preview_url: false, body: govde }
  };
}
function bos(v) { return String(v || '').trim(); }
function gosterim(t) { return t && t.includes('-') ? t.split('-').reverse().join('.') : t; }

const kayitlar = rows.filter((r) => bos(r.Telefon) === tel);
const teklifli = kayitlar.find((r) => bos(r.Durum).toLowerCase() === 'teklif_edildi');
const aktif = kayitlar
  .filter((r) => AKTIF.includes(bos(r.Durum).toLowerCase()))
  .sort((a, b) => bos(a.Tarih).localeCompare(bos(b.Tarih)))[0];
const kayit = teklifli || aktif;

// Tanimadigimiz numara ya da acik randevusu yok: insana devir.
if (!kayit) {
  return [{ json: { islem: 'devir', ID: '', tetikle_iptal: false, wa: mesaj('Merhaba, mesajınızı aldık. Danışmanımız en kısa sürede size dönecek. Acil durumlar için: ' + cfg.KLINIK_TELEFON) } }];
}

const simdi = $now.setZone('Europe/Istanbul').toFormat('yyyy-MM-dd HH:mm');

// ONAY
if (ONAY.includes(metin)) {
  if (bos(kayit.Durum).toLowerCase() === 'teklif_edildi') {
    const t = bos(kayit.TeklifTarih);
    const s = bos(kayit.TeklifSaat);
    // "Ilk yazan alir": slot baskasina gittiyse kapat.
    const dolu = rows.some((r) => bos(r.ID) !== bos(kayit.ID) && bos(r.Tarih) === t && bos(r.Saat) === s && ['onaylı', 'onayli', 'geldi'].includes(bos(r.Durum).toLowerCase()));
    if (dolu) {
      return [{ json: { islem: 'slot_dolu', ID: kayit.ID, Durum: 'bekleme', Tarih: bos(kayit.Tarih), Saat: bos(kayit.Saat), Guncelleme: simdi, tetikle_iptal: false, wa: mesaj('Maalesef o saat az önce doldu. Sizi bekleme listemizde tutuyoruz, ilk boşlukta yine ilk siz haberdar olacaksınız.') } }];
    }
    return [{ json: { islem: 'slot_verildi', ID: kayit.ID, Durum: 'onaylı', Tarih: t, Saat: s, Guncelleme: simdi, tetikle_iptal: false, wa: mesaj('Harika! Randevunuz ' + gosterim(t) + ' ' + s + ' olarak oluşturuldu. Görüşmek üzere.') } }];
  }
  return [{ json: { islem: 'onay', ID: kayit.ID, Durum: 'onaylı', Tarih: bos(kayit.Tarih), Saat: bos(kayit.Saat), Guncelleme: simdi, tetikle_iptal: false, wa: mesaj('Teşekkürler, randevunuz ' + gosterim(bos(kayit.Tarih)) + ' ' + bos(kayit.Saat) + ' için onaylandı.') } }];
}

// IPTAL / DEGISIKLIK
if (IPTAL.includes(metin)) {
  const durum = bos(kayit.Durum).toLowerCase();
  const teklifliMi = durum === 'teklif_edildi';
  // Henuz onaylanmamis lead "2" diyorsa teklif edilen saat uymamistir; hastayi kaybetme, listeye al.
  const onaylanmamis = durum === 'yeni';
  const beklemeyeGitsin = teklifliMi || onaylanmamis;
  // Koltuk gercekten bosaliyorsa (tarih/saat tutulmustu) doldurma akisini tetikle.
  const koltukBosaldi = !teklifliMi && bos(kayit.Tarih) !== '' && bos(kayit.Saat) !== '';

  let yanit;
  if (teklifliMi) yanit = 'Anlaşıldı, sizi bekleme listemizde tutuyoruz. Yeni bir boşluk açıldığında haber vereceğiz.';
  else if (onaylanmamis) yanit = 'Anlaşıldı, o saatler uymadı. Sizi bekleme listemize aldık; uygun bir boşluk açıldığında ilk siz haberdar olacaksınız.';
  else yanit = 'Randevunuz iptal edildi. Yeni bir randevu için bu mesaja yazmanız yeterli.';

  return [{
    json: {
      islem: beklemeyeGitsin ? 'beklemeye_alindi' : 'iptal',
      ID: kayit.ID,
      Durum: beklemeyeGitsin ? 'bekleme' : 'iptal',
      // Bekleme kaydinda tarih/saat tutulmaz, koltuk serbest kalir.
      Tarih: beklemeyeGitsin ? '' : bos(kayit.Tarih),
      Saat: beklemeyeGitsin ? '' : bos(kayit.Saat),
      Guncelleme: simdi,
      tetikle_iptal: koltukBosaldi,
      iptal_tarih: bos(kayit.Tarih),
      iptal_saat: bos(kayit.Saat),
      wa: mesaj(yanit)
    }
  }];
}

// DIGER: insana devir
return [{ json: { islem: 'devir', ID: '', tetikle_iptal: false, wa: mesaj('Mesajınızı aldık, danışmanımız en kısa sürede size dönecek. Randevunuzu onaylamak için 1, iptal/değişiklik için 2 yazabilirsiniz.') } }];
